import { emitEvent } from '@projexlight/sdk-audit';
await emitEvent({
  event_type: 'tenant.created.v1',
  payload: { tenant_id, app_id, region },
  pool_index: 'admin',
  actor_kind: 'service',
  actor_id: 'sdk-tenant.create',
  tenant_id,
  subject_kind: 'tenant',
  subject_id: tenant_id,
});

import { verifyChain } from '@projexlight/sdk-audit';
const result = await verifyChain({ tenant_id, since_seq: lastAttestedSeq });
if (!result.ok) {
  // PAGE OPERATOR — chain broken at result.broken_at_entry_id
}

import { startAuditVerifier } from '@projexlight/sdk-audit';
const worker = startAuditVerifier({ intervalMs: 86_400_000 });
// graceful shutdown:
await worker.stop();

import { requestExport } from '@projexlight/sdk-audit';
const { export_request_id } = await requestExport({
  tenant_id,
  subject_kind: 'person',
  subject_id: person_id,
  range_start, range_end,
});
// Customer polls /api/audit/exports/:id until status='signed', then downloads.

import { listEntries } from '@projexlight/sdk-audit';
const rows = await listEntries({
  tenant_id,
  actor_id: 'X',
  from: t1, to: t2,
  limit: 1000,
});
// rows are in seq order; chain_hash on the last row attests the chain was intact through that point.
